package xyz.kd5ujc.scarab.network

import cats.effect.{Deferred, IO, Ref, Resource}
import cats.syntax.all.*
import fs2.Stream
import munit.CatsEffectSuite
import scala.io.Source
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import xyz.kd5ujc.scarab.codec.Bytes
import xyz.kd5ujc.scarab.protocol.{BlockFetchEngine, ProtocolError}
import scala.concurrent.duration.*

/** Replays exact generic BlockFetch points, range requests, and block items generated by the pinned
  * upstream channel property. Mock Int-hash points remain opaque CBOR bytes; this does not claim
  * Cardano-ledger range-selection behavior or pipeline-trace equivalence.
  */
class UpstreamBlockFetchBehaviorSuite extends FailsOnUncaught:
  private val behaviorFixture =
    "/upstream/ouroboros-network-protocol-codecs/blockfetch-behavior.tsv"
  private val rangeFixture =
    "/upstream/ouroboros-network-protocol-codecs/blockfetch-behavior-ranges.tsv"
  private val expectedBehaviorSha =
    "26a4bc3528655096ea9f5e4df94c0e0b98525a14cfc6d77738f70c1ada571d36"
  private val expectedRangesSha = "2e8a66132dd77c38a142ed9d45a3141c10ad4cf3512b0ffb6a1a177b73136824"

  private enum Verdict:
    case Pass
    case Failure

  private final case class CaseRow(
      seed: Int,
      ordinal: Int,
      size: Int,
      expectedNewestFirst: Vector[Bytes],
      direct: Verdict,
      connect: Verdict,
      channel: Verdict
  )
  private final case class RangeRow(
      seed: Int,
      caseOrdinal: Int,
      rangeOrdinal: Int,
      from: Bytes,
      to: Bytes,
      bodies: Vector[Bytes]
  )

  private def readResource(path: String, expectedSha: String): Vector[String] =
    val stream =
      Option(getClass.getResourceAsStream(path)).getOrElse(fail(s"missing fixture $path"))
    val bytes = stream.readAllBytes()
    stream.close()
    val sha =
      MessageDigest.getInstance("SHA-256").digest(bytes).map(b => f"${b & 0xff}%02x").mkString
    assertEquals(sha, expectedSha, s"pinned fixture hash: $path")
    val source = Source.fromString(new String(bytes, StandardCharsets.UTF_8))
    try source.getLines().toVector
    finally source.close()

  private def fromHex(value: String): Bytes =
    Bytes.fromHex(value).fold(error => fail(s"invalid upstream CBOR hex: $error"), identity)

  private def verdict(value: String): Verdict = value match
    case "pass"             => Verdict.Pass
    case "upstream-failure" => Verdict.Failure
    case other              => fail(s"unknown upstream property verdict: $other")

  private def readCases(): Vector[CaseRow] =
    readResource(behaviorFixture, expectedBehaviorSha).map { line =>
      val fields = line.split("\\t", -1).toVector
      assertEquals(fields.size, 14)
      assertEquals(fields(0), "blockfetch-behavior-v1")
      val expectedItems =
        if fields(10).isEmpty then Vector.empty else fields(10).split(",", -1).toVector.map(fromHex)
      CaseRow(
        fields(1).toInt,
        fields(2).toInt,
        fields(3).toInt,
        expectedItems,
        verdict(fields(11)),
        verdict(fields(12)),
        verdict(fields(13))
      )
    }

  private def readRanges(): Vector[RangeRow] =
    readResource(rangeFixture, expectedRangesSha).map { line =>
      val fields = line.split("\\t", -1).toVector
      assert(fields.size >= 7, s"short generated range row: ${fields.size}")
      assertEquals(fields(0), "blockfetch-range-v1")
      val bodyCount = fields(6).toInt
      assertEquals(fields.size, 7 + bodyCount, "body count agrees with original serialized list")
      RangeRow(
        fields(1).toInt,
        fields(2).toInt,
        fields(3).toInt,
        fromHex(fields(4)),
        fromHex(fields(5)),
        fields.drop(7).map(fromHex)
      )
    }

  private val pointCodec: BlockFetchEngine.PointCodec[Bytes] =
    BlockFetchEngine.pointCodec[Bytes](Right(_), Right(_))

  private val payloadCodec: BlockFetchEngine.PayloadCodec[Bytes] =
    new BlockFetchEngine.PayloadCodec[Bytes]:
      def encode(value: Bytes): Either[ProtocolError, Bytes] = Right(value)
      def decode(value: Bytes): Either[ProtocolError, Bytes] = Right(value)

  private final class OracleBlocks(rows: Vector[RangeRow])
      extends BlockFetchRuntime.Blocks[IO, Bytes, Bytes]:
    private val ranges: Map[(Bytes, Bytes), Vector[Bytes]] =
      rows.groupBy(row => (row.from, row.to)).map { case (key, aliases) =>
        val expected = aliases.head.bodies
        assert(
          aliases.forall(_.bodies == expected),
          s"upstream generated range alias conflict for $key"
        )
        key -> expected
      }

    def range(from: Bytes, to: Bytes): IO[Option[Stream[IO, Bytes]]] =
      IO.pure(ranges.get((from, to)).filter(_.nonEmpty).map(Stream.emits))

  test("production generic BlockFetch runtime replays unchanged upstream channel range rows"):
    val cases = readCases()
    val ranges = readRanges()
    assertEquals(cases.size, 24)
    assertEquals(cases.map(_.seed), Vector.range(490201, 490225))
    assertEquals(cases.map(_.ordinal), Vector.range(0, 24))
    assertEquals(cases.map(_.size), (0 until 24).map(i => 30 + i % 21).toVector)
    assertEquals(cases.count(_.direct == Verdict.Pass), 24)
    assertEquals(cases.count(_.connect == Verdict.Pass), 24)
    assertEquals(cases.count(_.channel == Verdict.Pass), 24)
    assertEquals(ranges.size, 298)
    assertEquals(ranges.map(_.bodies.size).sum, 694)
    assertEquals(ranges.count(_.bodies.isEmpty), 180)
    assertEquals(ranges.map(row => (row.seed, row.caseOrdinal)).distinct.size, 24)

    cases.traverse_ { testCase =>
      val caseRanges = ranges
        .filter(row => row.seed == testCase.seed && row.caseOrdinal == testCase.ordinal)
        .sortBy(_.rangeOrdinal)
      assertEquals(
        caseRanges.map(_.rangeOrdinal),
        Vector.range(0, caseRanges.size),
        s"seed ${testCase.seed} contiguous range identities"
      )
      val serverBlocks = new OracleBlocks(caseRanges)
      val clientSettings = BlockFetchRuntime.ClientSettings(
        request = BlockFetchEngine.RequestLimits(maxBlocks = 128)
      )
      Peers
        .typed {
          Peers.linked(protocols = Set(Protocols.BlockFetch)).use { case (clientMux, serverMux) =>
            for
              clientChannel <- clientMux.channel(Protocols.BlockFetch)
              serverChannel <- serverMux.channel(Protocols.BlockFetch)
              _ <- cats.effect.Resource
                .make(
                  Fibers
                    .scoped[IO, NetworkError, Unit](NetworkError.Defect(_)) {
                      BlockFetchRuntime
                        .run(
                          serverChannel,
                          serverBlocks,
                          pointCodec,
                          payloadCodec,
                          (from, to) => Right((from, to)),
                          BlockFetchRuntime
                            .ServerSettings(idleTimeout = 10.seconds)
                        )
                    }
                    .start
                )(_.cancel)
                .use { serverFiber =>
                  BlockFetchRuntime
                    .resource(
                      clientChannel,
                      pointCodec,
                      payloadCodec,
                      _.size,
                      clientMux.abort,
                      clientSettings
                    )
                    .use { client =>
                      for
                        streamed <- Ref.of[IO, Map[Int, Vector[Bytes]]](Map.empty)
                        responses <- caseRanges
                          .traverse { range =>
                            for
                              sent <- Resource.eval(Deferred[IO, Unit])
                              reply <- Resource.make(
                                Fibers
                                  .scoped[IO, NetworkError, Option[Vector[Bytes]]](
                                    NetworkError.Defect(_)
                                  ) {
                                    client.requestRangeStreaming(range.from, range.to)(
                                      body =>
                                        streamed
                                          .update(
                                            _.updatedWith(range.rangeOrdinal)(previous =>
                                              Some(previous.getOrElse(Vector.empty) :+ body)
                                            )
                                          )
                                          .as(Right(())),
                                      {
                                        case _: BlockFetchRuntime.Event.Sent =>
                                          sent.complete(()).void
                                        case _ => IO.unit
                                      }
                                    )
                                  }
                                  .start
                              )(_.cancel)
                              // Keep the original upstream range order while overlapping responses.
                              _ <- Resource.eval(IO.race(sent.get, reply.joinWithNever).flatMap {
                                case Left(_) => IO.unit
                                case Right(early) =>
                                  Fibers.land[IO, NetworkError, Option[Vector[Bytes]]](early).void
                              })
                            yield range -> reply
                          }
                          .use(_.traverse { (range, reply) =>
                            reply.joinWithNever.flatMap(Fibers.land(_)).map(range -> _)
                          })
                        delivered <- streamed.get
                        _ <- client.done
                        serverResult <- serverFiber.joinWithNever
                        _ <- Fibers.land[IO, NetworkError, Unit](serverResult)
                        _ <- IO {
                          responses.foreach { case (range, actual) =>
                            val expected = Option.when(range.bodies.nonEmpty)(range.bodies)
                            assertEquals(
                              delivered.getOrElse(range.rangeOrdinal, Vector.empty),
                              range.bodies,
                              s"seed ${testCase.seed}, streamed bodies of range ${range.rangeOrdinal}"
                            )
                            assertEquals(
                              actual,
                              expected,
                              s"seed ${testCase.seed}, range ${range.rangeOrdinal}"
                            )
                          }
                          val inWireOrder = responses.flatMap(_._2.getOrElse(Vector.empty))
                          val sourceResponseOrder = caseRanges.flatMap(_.bodies)
                          assertEquals(
                            inWireOrder,
                            sourceResponseOrder,
                            s"seed ${testCase.seed} upstream server response order"
                          )
                          assertEquals(
                            inWireOrder.reverse,
                            testCase.expectedNewestFirst,
                            s"seed ${testCase.seed} original prop_connect/channel result order"
                          )
                        }
                      yield ()
                    }
                }
            yield ()
          }
        }
        .map(result => assertEquals(result, Right(()), s"seed ${testCase.seed}"))
    }
